/* ============================================
   页面转场动画
   ============================================ */

@keyframes slide-in-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes slide-up {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes page-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

.tf-cg-carousel{box-sizing:border-box;}.tf-cg-carousel__main{box-sizing:border-box;}.tf-cg-carousel__counter{box-sizing:border-box;backdrop-filter:blur(4px);}.tf-cg-carousel__dots{box-sizing:border-box;}
